mapper.select:
SELECT u.id, u.username, u.email, u.nickname, u.role, u.avatar_url as avatarUrl, u.bio, u.points, u.status, u.last_login_at as lastLoginAt, u.password_hash as passwordHash, u.created_at as createdAt, u.updated_at as updatedAt, u.deleted_at as deletedAt, COALESCE(COUNT(DISTINCT p.id), 0) as postCount FROM users u LEFT JOIN posts p ON u.id = p.author_id AND p.deleted_at IS NULL
AND u.username LIKE CONCAT('%', #{username}, '%')
AND u.email LIKE CONCAT('%', #{email}, '%')
AND u.role = #{role}
AND u.status = #{status}
AND u.deleted_at IS NULL
GROUP BY u.id, u.username, u.email, u.nickname, u.role, u.avatar_url, u.bio, u.points, u.status, u.last_login_at, u.password_hash, u.created_at, u.updated_at, u.deleted_at ORDER BY u.created_at DESC LIMIT #{offset}, #{limit}

SELECT COUNT(DISTINCT u.id) FROM users u
AND u.username LIKE CONCAT('%', #{username}, '%')
AND u.email LIKE CONCAT('%', #{email}, '%')
AND u.role = #{role}
AND u.status = #{status}
AND u.deleted_at IS NULL

mapper.update:
UPDATE users
SET points = points - #{amount},
    version = #{newVersion},
    updated_at = NOW()
WHERE id = #{userId}
AND version = #{currentVersion}
AND points >= #{amount}

UPDATE users
SET points = points + #{amount},
    version = #{newVersion},
    updated_at = NOW()
WHERE id = #{userId}
AND version = #{currentVersion}
